conditionGuides:
/** SPARK component name=RendererFilterExpression */
r-filter-expression按完整视图键、数据成员和字段定位定义，写回原DataView编辑域。
type RFilterExpressionProps {
  过滤条件可使用的字段元信息，不是业务结果行；异步更新保留未应用草稿，应用时按最新目录校验。
  columns: DataColumn[]
}

/** SPARK component name=RendererFilterExpression */
r-filter-expression按完整视图键、数据成员和字段定位定义，写回原DataView编辑域。
type RFilterExpressionProps {
  tree保存原生树（清空为undefined）；spark-json保存数据库SPARK文本（清空为空字符串）。
  readonly format: "tree" | "spark-json"
}

/** SPARK component name=RendererFilterExpression */
r-filter-expression按完整视图键、数据成员和字段定位定义，写回原DataView编辑域。
type RFilterExpressionProps {
  存在未应用草稿或编辑弹窗时通知true；取消、原DataView显式取消本行/全部行、应用接受、换绑定、失权及释放后通知false。取消其他行保留本行未应用输入。
  onEditingChange(editing: boolean): void
}
